function GIRTH(adj):
  best <- +infinity
  for each src in V:
    dist[src] <- 0; parent[src] <- src; Q <- [src]
    while Q non-empty:
      u <- dequeue(Q)
      for w in adj[u]:
        if w not visited:
          dist[w] <- dist[u]+1; parent[w] <- u; enqueue(Q, w)
        else if parent[u] != w:
          best <- min(best, dist[u]+dist[w]+1)
  return best

