function MIN_DISTANCE(inc):
  rights <- union of inc[l] over all l
  for size = 1 .. |L|:
    for each S subset of L with |S| = size:
      counts[r] <- number of l in S with r in inc[l]
      if counts[r] even for all r in rights:
        return (size, S)
  return (0, empty)   // only the zero codeword

