from itertools import combinations
from typing import Dict, List, Set, Tuple

Incidence = Dict[int, Set[int]]  # left vertex -> right neighbours

def minimum_distance(inc: Incidence) -> Tuple[int, List[int]]:
    """Exact minimum distance of B(G): smallest non-empty S whose every right
    vertex has even S-degree. Enumerates left-subsets by increasing size.

    Complexity O(2^|L| * d) worst case; exact for small Tanner graphs.
    """
    rights: Set[int] = set().union(*inc.values()) if inc else set()
    left = sorted(inc)
    for size in range(1, len(left) + 1):
        for S in combinations(left, size):
            counts = {r: 0 for r in rights}
            for l in S:
                for r in inc[l]:
                    counts[r] += 1
            if all(c % 2 == 0 for c in counts.values()):
                return size, list(S)
    return 0, []

from typing import Dict, List, Optional, Set, Tuple

Incidence = Dict[int, Set[int]]
Vertex = Tuple[str, int]

def extract_cycle_from_codeword(inc: Incidence, S: Set[int]) -> Optional[List[Vertex]]:
    """Constructive heart of the theorem: from a non-empty codeword S, build the
    restricted graph G|_S (edges incident to a left vertex in S) and return a
    cycle. Since every left vertex of G|_S has degree d >= 2 and every right
    vertex has even (hence 0 or >= 2) degree, no vertex has degree 1, so a cycle
    must exist. Its length equals 2 * (distinct left vertices visited) <= 2|S|.
    """
    adj: Dict[Vertex, Set[Vertex]] = {}
    for l in S:
        adj.setdefault(("L", l), set())
        for r in inc[l]:
            adj.setdefault(("R", r), set())
            adj[("L", l)].add(("R", r))
            adj[("R", r)].add(("L", l))
    visited: Set[Vertex] = set()
    parent: Dict[Vertex, Optional[Vertex]] = {}

    def dfs(u: Vertex, p: Optional[Vertex]) -> Optional[List[Vertex]]:
        visited.add(u); parent[u] = p
        for w in adj[u]:
            if w == p:
                continue
            if w in visited:
                cyc = [u]; cur = u
                while cur != w:
                    cur = parent[cur]; cyc.append(cur)
                return cyc
            res = dfs(w, u)
            if res is not None:
                return res
        return None

    for start in adj:
        if start not in visited:
            c = dfs(start, None)
            if c is not None:
                return c
    return None

